import React, { useState } from 'react';
import {} from 'react-router-dom';

const CardReservation = () => {
 
  const [formData, setFormData] = useState({
    dateRetrait: '',
    heureRetrait: '10:00',
    dateRetour: '',
    heureRetour: '10:00',
    transmission: 'Manuelle',
    siege: '4',
    categorie: 'Berline',
    carburant: 'Diesel'
  });

  const handleChange = (e) => {
    const { name, value } = e.target;
    setFormData(prev => ({
      ...prev,
      [name]: value
    }));
  };

  const handleSubmit = (e) => {
    e.preventDefault();
    // Validation des dates
    if (new Date(formData.dateRetour) <= new Date(formData.dateRetrait)) {
      alert("La date de retour doit être après la date de retrait");
      return;
    }
    
    // Enregistrement des données et redirection
    localStorage.setItem('reservationData', JSON.stringify(formData));
   
  };

  // Valeurs par défaut pour aujourd'hui et +2 jours
  const today = new Date().toISOString().split('T')[0];
  const defaultReturnDate = new Date();
  defaultReturnDate.setDate(defaultReturnDate.getDate() + 2);
  const defaultReturnDateStr = defaultReturnDate.toISOString().split('T')[0];

  return (
    <div className="max-w-md mx-auto p-6 bg-white rounded-lg shadow-md">
      <h1 className="text-xl font-bold mb-4">Réservation de véhicule</h1>
      <h2 className="text-lg font-semibold mb-2">Aéroport Tunis Carthage</h2>
      
      <form onSubmit={handleSubmit}>
        <div className="grid grid-cols-2 gap-4 mb-4">
          <div>
            <label className="block text-sm font-medium mb-1">Date de retrait*</label>
            <input
              type="date"
              name="dateRetrait"
              value={formData.dateRetrait || today}
              onChange={handleChange}
              min={today}
              className="w-full p-2 border rounded"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Heure*</label>
            <input
              type="time"
              name="heureRetrait"
              value={formData.heureRetrait}
              onChange={handleChange}
              className="w-full p-2 border rounded"
              required
            />
          </div>
        </div>

        <div className="grid grid-cols-2 gap-4 mb-6">
          <div>
            <label className="block text-sm font-medium mb-1">Date de retour*</label>
            <input
              type="date"
              name="dateRetour"
              value={formData.dateRetour || defaultReturnDateStr}
              onChange={handleChange}
              min={formData.dateRetrait || today}
              className="w-full p-2 border rounded"
              required
            />
          </div>
          <div>
            <label className="block text-sm font-medium mb-1">Heure*</label>
            <input
              type="time"
              name="heureRetour"
              value={formData.heureRetour}
              onChange={handleChange}
              className="w-full p-2 border rounded"
              required
            />
          </div>
        </div>

        <div className="mb-6">
          <h3 className="font-medium mb-2">Préférences du véhicule</h3>
          <div className="grid grid-cols-2 gap-4">
            <div>
              <label className="block text-sm font-medium mb-1">Transmission</label>
              <select
                name="transmission"
                value={formData.transmission}
                onChange={handleChange}
                className="w-full p-2 border rounded"
              >
                <option value="Manuelle">Manuelle</option>
                <option value="Automatique">Automatique</option>
                <option value="Semi-automatique">Semi-automatique</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Sièges</label>
              <select
                name="siege"
                value={formData.siege}
                onChange={handleChange}
                className="w-full p-2 border rounded"
              >
                {[2, 4, 5, 7, 9].map(num => (
                  <option key={num} value={num}>{num} sièges</option>
                ))}
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Catégorie</label>
              <select
                name="categorie"
                value={formData.categorie}
                onChange={handleChange}
                className="w-full p-2 border rounded"
              >
                <option value="Economique">Economique</option>
                <option value="Compacte">Compacte</option>
                <option value="Berline">Berline</option>
                <option value="SUV">SUV</option>
                <option value="Monospace">Monospace</option>
              </select>
            </div>
            <div>
              <label className="block text-sm font-medium mb-1">Carburant</label>
              <select
                name="carburant"
                value={formData.carburant}
                onChange={handleChange}
                className="w-full p-2 border rounded"
              >
                <option value="Essence">Essence</option>
                <option value="Diesel">Diesel</option>
                <option value="Electrique">Electrique</option>
                <option value="Hybride">Hybride</option>
                <option value="GPL">GPL</option>
              </select>
            </div>
          </div>
        </div>

        <button
          type="submit"
          className="w-full bg-blue-600 text-white py-3 px-4 rounded-md hover:bg-blue-700 transition-colors shadow-md"
        >
          Trouver une voiture
        </button>
      </form>
    </div>
  );
};

export default CardReservation;
